# mean_var :: [1, 2, 3, 4, 5]
def mean_var(xs):
    if not xs:
        return 0.0, 0.0
    m = sum(xs) / len(xs)
    v = sum((x - m) ** 2 for x in xs) / len(xs)
    return m, v

if __name__ == '__main__':
    print(mean_var([1, 2, 3, 4, 5]))

